SELECT 100.0 * COUNT(DISTINCT CASE WHEN UA <= 6.5 THEN ID END) / COUNT(DISTINCT ID)
FROM Laboratory
WHERE "U-PRO" > 0 AND "U-PRO" < 30;

SELECT b.molecule_id, b.bond_type
FROM bond b
WHERE b.molecule_id >= 'TR000' AND b.molecule_id <= 'TR050';

SELECT (SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) * 100.0) / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT MAX(`Free Meal Count (K-12)` / NULLIF(`Enrollment (K-12)`, 0)) AS max_eligible_free_rate
FROM frpm
WHERE `County Name` = 'Alameda';

SELECT CAST(SUM(CASE WHEN DOC = 54 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN DOC = 52 THEN 1 ELSE 0 END) AS ratio
FROM schools
WHERE StatusType = 'Merged' AND County = 'Orange';

SELECT SUM(CASE WHEN FundingType = 'Locally funded' THEN 1 ELSE 0 END) * 100.0 / COUNT(FundingType) AS ratio_percentage
FROM schools
WHERE County = 'Santa Clara';

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT Reputation, Views
FROM users
WHERE DisplayName = 'Jarrod Dixon';

SELECT SUM(CASE WHEN Currency = 'Euro' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS PercentageOfKAMUsingEuro
FROM customers
WHERE Segment = 'KAM';

SELECT CAST(COUNT(DISTINCT CASE WHEN Consumption > 528.3 THEN CustomerID END) AS REAL) * 100.0 / COUNT(DISTINCT CustomerID) AS percentage
FROM yearmonth
WHERE Date LIKE '201202%';

SELECT SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS percentage
FROM gasstations
WHERE Country = 'Slovakia';

SELECT SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS premium_percentage
FROM gasstations
WHERE Country = 'SVK';

SELECT SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) * 100.0 / SUM(amount) AS percentage
FROM loan
WHERE amount < 100000;

SELECT A3, A2
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT
  (SELECT frequency FROM account WHERE account_id = 3) AS statement_frequency,
  (SELECT k_symbol FROM trans WHERE trans_id = 3539 AND type = 'VYDAJ') AS debit_purpose;

SELECT strftime('%Y', birth_date) AS birth_year
FROM client
WHERE client_id = 130;

SELECT SUM(cost) AS total_pizza_cost
FROM expense
WHERE expense_description = 'Pizza';

SELECT SUM(major.major_name = 'Finance') / SUM(major.major_name = 'Physics') AS ratio
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT SUM(m.position = 'Member' AND mj.major_name = 'Business') * 100.0 / COUNT(m.member_id) AS percentage
FROM member m
JOIN major mj ON m.link_to_major = mj.major_id;

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT first_name, last_name
FROM member
WHERE t_shirt_size = 'X-Large';

SELECT SUM(CASE WHEN c.colour = 'Blue' THEN 1 ELSE 0 END) * 100.0 / COUNT(s.superhero_name) AS percentage
FROM superhero s
LEFT JOIN colour c ON s.eye_colour_id = c.id;

SELECT CAST(COUNT(CASE WHEN Admission = '+' THEN 1 END) AS REAL) / COUNT(CASE WHEN Admission = '-' THEN 1 END) AS ratio
FROM Patient
WHERE Diagnosis = 'SLE';

SELECT CAST(COUNT(DISTINCT CASE WHEN P.SEX = 'F' AND (CAST(L.TP AS REAL) < 6.0 OR CAST(L.TP AS REAL) > 8.5) THEN P.ID END) AS REAL) * 100.0 / COUNT(DISTINCT L.ID) AS percentage
FROM Patient AS P
JOIN Laboratory AS L ON P.ID = L.ID;

SELECT CAST(COUNT(DISTINCT CASE WHEN UA <= 6.5 THEN ID END) AS REAL) * 100 / COUNT(DISTINCT ID) AS percentage
FROM Laboratory
WHERE `U-PRO` > 0 AND `U-PRO` < 30;

SELECT bond_id
FROM connected
WHERE atom_id2 = (SELECT atom_id2 FROM connected WHERE atom_id = 'TR000_2');

SELECT COUNT(DISTINCT bond_id) AS num_connections
FROM connected
WHERE atom_id LIKE 'TR%_19' OR atom_id2 LIKE 'TR%_19';

SELECT SUM(CASE WHEN bond_type = ' = ' THEN 1 ELSE 0 END) * 100.0 / COUNT(bond_id) AS percent
FROM bond
WHERE molecule_id = 'TR047';

SELECT 100.0 * SUM(CASE WHEN molecule.label = '+' AND atom.element = 'h' THEN 1 ELSE 0 END) / COUNT(molecule.molecule_id) AS percentage
FROM molecule
JOIN atom ON molecule.molecule_id = atom.molecule_id;

SELECT CAST(SUM(CASE WHEN b.bond_type = '-' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(c.bond_id) AS percentage
FROM connected c
JOIN bond b ON c.bond_id = b.bond_id;

SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT
  (SELECT COUNT(*) FROM posts WHERE OwnerUserId = (SELECT Id FROM users ORDER BY CreationDate DESC LIMIT 1)) AS post_count,
  (SELECT COUNT(*) FROM comments WHERE UserId = (SELECT Id FROM users ORDER BY CreationDate DESC LIMIT 1)) AS comment_count;

SELECT AVG(CASE WHEN p.player_name = 'Abdou Diallo' THEN pa.ball_control END) - AVG(CASE WHEN p.player_name = 'Aaron Appindangoye' THEN pa.ball_control END) AS ball_control_difference
FROM Player p
JOIN Player_Attributes pa ON p.player_api_id = pa.player_api_id;

SELECT SUM(home_team_goal) 
FROM Match 
WHERE (SELECT player_api_id FROM Player WHERE player_name = 'Aaron Lennon') IN (home_player_1, home_player_2, home_player_3, home_player_4, home_player_5, home_player_6, home_player_7, home_player_8, home_player_9, home_player_10, home_player_11);

SELECT (
  (SELECT balance FROM trans WHERE account_id = (SELECT account_id FROM loan WHERE date = '1993-07-05' ORDER BY date LIMIT 1) AND date = '1998-12-27' LIMIT 1)
  -
  (SELECT balance FROM trans WHERE account_id = (SELECT account_id FROM loan WHERE date = '1993-07-05' ORDER BY date LIMIT 1) AND date = '1993-03-22' LIMIT 1)
) * 100.0 / (SELECT balance FROM trans WHERE account_id = (SELECT account_id FROM loan WHERE date = '1993-07-05' ORDER BY date LIMIT 1) AND date = '1993-03-22' LIMIT 1) AS increase_rate;

SELECT SUM(CASE WHEN member.position = 'Member' AND major.major_name = 'Business' THEN 1 ELSE 0 END) * 100.0 / COUNT(member.member_id) AS percentage
FROM member
JOIN major ON member.link_to_major = major.major_id;

SELECT CAST(SUM(CASE WHEN P.SEX = 'F' AND (CAST(L.TP AS REAL) < 6.0 OR CAST(L.TP AS REAL) > 8.5) THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(L.ID)
FROM Patient AS P
INNER JOIN Laboratory AS L ON P.ID = L.ID;

SELECT SUM(CASE WHEN P.SEX = 'M' AND L.UA <= '8.0' THEN 1 ELSE 0 END) * 1.0 / SUM(CASE WHEN P.SEX = 'F' AND L.UA <= '6.5' THEN 1 ELSE 0 END)
FROM Patient P
JOIN Laboratory L ON P.ID = L.ID;

SELECT atom_id FROM connected WHERE atom_id2 IN (SELECT atom_id FROM atom WHERE element = 'pb')
UNION
SELECT atom_id2 FROM connected WHERE atom_id IN (SELECT atom_id FROM atom WHERE element = 'pb');
